comp = str.maketrans("ACGT","TGCA")
def rc(s): return s.translate(comp)[::-1]

def orfs(s, strand):
    res=[]
    stops = {"TAA","TAG","TGA"}
    for frame in range(3):
        i=frame
        start=None
        while i < len(s)-2:
            cod = s[i:i+3]
            if cod=="ATG" and start is None:
                start=i
            if cod in stops:
                if start is not None:
                    res.append((start,i+3,i+3-start))
                start=None
            i+=3
        if start is not None:
            res.append((start,len(s),len(s)-start))
    return res

