# implement without numpy
def sw(a,b,ma=1,mi=-1,g=-2):
    n,m=len(a),len(b)
    H=[[0]*(m+1) for _ in range(n+1)]
    best=0; bi=bj=0
    for i in range(1,n+1):
        for j in range(1,m+1):
            d=H[i-1][j-1]+(ma if a[i-1]==b[j-1] else mi)
            u=H[i-1][j]+g; l=H[i][j-1]+g
            H[i][j]=max(0,d,u,l)
            if H[i][j]>best: best=H[i][j]; bi,bj=i,j
    # traceback
    i,j=bi,bj; A=[];B=[]
    while i>0 and j>0 and H[i][j]>0:
        if H[i][j]==H[i-1][j-1]+(ma if a[i-1]==b[j-1] else mi):
            A.append(a[i-1]);B.append(b[j-1]);i-=1;j-=1
        elif H[i][j]==H[i-1][j]+g:
            A.append(a[i-1]);B.append('-');i-=1
        else:
            A.append('-');B.append(b[j-1]);j-=1
    return best,"".join(reversed(A)),"".join(reversed(B))
